require "application_system_test_case"

class LayoutCheckTest < ApplicationSystemTestCase
  test "verify preview boosts and comments layout" do
    sign_in_as users(:david)

    cards(:logo).reactions.create!(content: "🚀", reacter: users(:david))
    cards(:shipping).reactions.create!(content: "🔥", reacter: users(:david))

    visit board_url(boards(:writebook))
    col = find("##{dom_id(columns(:writebook_triage))}")
    col.find(".cards__expander").click if col[:class].include?("is-collapsed")

    [ cards(:logo), cards(:layout), cards(:shipping) ].each do |card|
      article_id = dom_id(card, :article)
      assert_selector "##{article_id}"
      rects = page.evaluate_script(<<~JS)
        (() => {
          const card = document.getElementById("#{article_id}");
          const r = (sel) => {
            const el = card.querySelector(sel);
            return el ? el.getBoundingClientRect() : null;
          };
          return JSON.stringify({
            card: card.getBoundingClientRect(),
            footer: r(".card__footer"),
            meta: r(".card__meta"),
            boosts: r(".card__boosts"),
            comments: r(".card__comments")
          });
        })()
      JS
      puts "#{card.title}: #{rects}"
    end
  end
end
EOF
